def cli(ctx, debug, disable_optional_telemetry):
    ctx.ensure_object(dict)
    if ctx.obj is None or not isinstance(ctx.obj, dict):
        ctx.obj = {}
    if not hasattr(ctx.obj, 'auth'):
        from safety.auth.models import AuthSession
        ctx.obj = SafetyCLI(auth=AuthSession(), config=SafetyCLI.config)
    if ctx.obj.auth is None:
        from safety.auth.models import AuthSession
        ctx.obj.auth = AuthSession()

def clean_check_command(f):
    @wraps(f)
    def inner(ctx, *args, **kwargs):
        kwargs.pop("key", None)
        kwargs.pop('proxy_protocol', None)
        kwargs.pop('proxy_host', None)
        kwargs.pop('proxy_port', None)
        return f(ctx, *args, **kwargs)
    return inner
